176	                >
177	                  {task.done ? 'Reopen' : 'Tick off'}
178	                </button>
179	              </td>
180	            </tr>
181	          ))}
182	        </tbody>
183	      </table>
184	
185	      <h2>Invoices</h2>
186	
187	      {openInvoiceId !== null ? (
188	        <InvoiceLineItems
189	          invoiceId={openInvoiceId}
190	          onBack={() => {
