206	            Enter an amount greater than zero.
207	          </p>
208	        )}
209	        <button data-testid="invoice-form-submit" type="submit">
210	          Add invoice
211	        </button>
212	      </form>
213	
214	      <button data-testid="invoice-sort-due" type="button" onClick={onSortByDue}>
215	        Sort by due date
216	      </button>
217	
218	      <table data-testid="project-invoices-table">
219	        <thead>
220	          <tr>
221	            <th>Amount</th>
222	            <th>Left to pay</th>
223	            <th>Issued</th>
224	            <th>Due</th>
225	            <th>Status</th>
226	            <th></th>
227	          </tr>
228	        </thead>
229	        <tbody>
230	          {invoices.map((invoice) => (
231	            <tr key={invoice.id} data-testid={`invoice-row-${invoice.id}`}>
232	              <td data-testid="invoice-amount">{formatMoney(invoice.amount)}</td>
233	              <td data-testid="invoice-due-amount">{formatMoney(invoice.dueAmount)}</td>
234	              <td data-testid="invoice-issued">{invoice.issuedDate}</td>
235	              <td data-testid="invoice-due">{invoice.dueDate}</td>
236	              <td data-testid="invoice-status">{invoice.status}</td>
237	              <td>
238	                <button
239	                  data-testid={`invoice-open-${invoice.id}`}
240	                  type="button"
241	                  onClick={() => setOpenInvoiceId(invoice.id)}
242	                >
243	                  Open
244	                </button>
245	                {/* Lifecycle: a DRAFT can be sent. Once sent, the status is worked out from the
246	                    payments recorded against the invoice — PARTIAL then PAID — not flipped by hand. */}
