13	
14	/**
15	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
16	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
17	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
18	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
19	 */
20	@Profile("harness")
21	@RestController
22	@RequestMapping("/__test__")
23	public class TestSupportController {
24	
25	    private final Audit audit;
26	    private final JdbcTemplate jdbc;
27	
28	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
29	        this.audit = audit;
30	        this.jdbc = jdbc;
31	    }
32	
33	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
34	    @PostMapping("/reset")
35	    public void reset() {
36	        audit.clear();
37	        // Disable FK checks so a referenced parent (clients) can be truncated alongside its child.
38	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
39	        jdbc.execute("TRUNCATE TABLE payments RESTART IDENTITY");
40	        jdbc.execute("TRUNCATE TABLE line_items RESTART IDENTITY");
41	        jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
42	        jdbc.execute("TRUNCATE TABLE contacts RESTART IDENTITY");
43	        jdbc.execute("TRUNCATE TABLE tasks RESTART IDENTITY");
44	        jdbc.execute("TRUNCATE TABLE notes RESTART IDENTITY");
45	        jdbc.execute("TRUNCATE TABLE project_tags RESTART IDENTITY");
46	        jdbc.execute("TRUNCATE TABLE tags RESTART IDENTITY");
47	        jdbc.execute("TRUNCATE TABLE projects RESTART IDENTITY");
48	        jdbc.execute("TRUNCATE TABLE clients RESTART IDENTITY");
49	        jdbc.execute("TRUNCATE TABLE dashboard_settings");
50	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
51	    }
52	
53	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
54	    @PostMapping("/seed")
55	    @SuppressWarnings("unchecked")
56	    public void seed(@RequestBody Map<String, Object> fixture) {
57	        // The dashboard measures invoice "overdue" against a fixed reference date; store it when the
58	        // fixture supplies one so the home-screen count is deterministic.
59	        Object asOf = fixture.get("asOf");
60	        if (asOf != null) {
61	            jdbc.update("INSERT INTO dashboard_settings (id, as_of) VALUES (1, ?)", asOf.toString());
62	        }
63	
64	        List<Map<String, Object>> clients =
65	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
66	        long maxClientId = 0;
67	        for (Map<String, Object> client : clients) {
68	            long id = ((Number) client.get("id")).longValue();
69	            // Seed with the fixture's explicit id (JdbcTemplate, not JPA) so specs can assert by id.
70	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
71	                    id, client.get("name"), client.get("email"));
72	            maxClientId = Math.max(maxClientId, id);
73	        }
74	        if (maxClientId > 0) {
75	            // Advance the identity so app-generated ids don't collide with seeded rows.
76	            jdbc.execute("ALTER TABLE clients ALTER COLUMN id RESTART WITH " + (maxClientId + 1));
77	        }
78	
79	        List<Map<String, Object>> projects =
80	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
81	        long maxProjectId = 0;
82	        for (Map<String, Object> project : projects) {
83	            long id = ((Number) project.get("id")).longValue();
84	            long clientId = ((Number) project.get("clientId")).longValue();
85	            String status = (String) project.getOrDefault("status", "ACTIVE");
86	            boolean archived = Boolean.TRUE.equals(project.getOrDefault("archived", Boolean.FALSE));
87	            double budget = ((Number) project.getOrDefault("budget", 0)).doubleValue();
88	            jdbc.update(
89	                    "INSERT INTO projects (id, name, client_id, status, archived, budget) VALUES (?, ?, ?, ?, ?, ?)",
90	                    id, project.get("name"), clientId, status, archived, budget);
91	            maxProjectId = Math.max(maxProjectId, id);
92	        }
93	        if (maxProjectId > 0) {
94	            jdbc.execute("ALTER TABLE projects ALTER COLUMN id RESTART WITH " + (maxProjectId + 1));
95	        }
96	
97	        List<Map<String, Object>> contacts =
98	                (List<Map<String, Object>>) fixture.getOrDefault("contacts", List.of());
99	        long maxContactId = 0;
100	        for (Map<String, Object> contact : contacts) {
101	            long id = ((Number) contact.get("id")).longValue();
102	            long clientId = ((Number) contact.get("clientId")).longValue();
103	            boolean primary = Boolean.TRUE.equals(contact.getOrDefault("primary", Boolean.FALSE));
104	            jdbc.update(
105	                    "INSERT INTO contacts (id, client_id, name, email, role, is_primary) VALUES (?, ?, ?, ?, ?, ?)",
106	                    id, clientId, contact.get("name"), contact.get("email"), contact.get("role"),
107	                    primary);
108	            maxContactId = Math.max(maxContactId, id);
109	        }
110	        if (maxContactId > 0) {
111	            jdbc.execute("ALTER TABLE contacts ALTER COLUMN id RESTART WITH " + (maxContactId + 1));
112	        }
113	
114	        List<Map<String, Object>> tasks =
115	                (List<Map<String, Object>>) fixture.getOrDefault("tasks", List.of());
116	        long maxTaskId = 0;
117	        for (Map<String, Object> task : tasks) {
118	            long id = ((Number) task.get("id")).longValue();
119	            long projectId = ((Number) task.get("projectId")).longValue();
120	            boolean done = Boolean.TRUE.equals(task.getOrDefault("done", Boolean.FALSE));
121	            jdbc.update("INSERT INTO tasks (id, project_id, title, done) VALUES (?, ?, ?, ?)",
122	                    id, projectId, task.get("title"), done);
123	            maxTaskId = Math.max(maxTaskId, id);
124	        }
125	        if (maxTaskId > 0) {
126	            jdbc.execute("ALTER TABLE tasks ALTER COLUMN id RESTART WITH " + (maxTaskId + 1));
127	        }
128	
129	        List<Map<String, Object>> tags =
130	                (List<Map<String, Object>>) fixture.getOrDefault("tags", List.of());
131	        long maxTagId = 0;
132	        for (Map<String, Object> tag : tags) {
133	            long id = ((Number) tag.get("id")).longValue();
134	            jdbc.update("INSERT INTO tags (id, name) VALUES (?, ?)", id, tag.get("name"));
135	            maxTagId = Math.max(maxTagId, id);
136	        }
137	        if (maxTagId > 0) {
138	            jdbc.execute("ALTER TABLE tags ALTER COLUMN id RESTART WITH " + (maxTagId + 1));
139	        }
140	
141	        List<Map<String, Object>> projectTags =
142	                (List<Map<String, Object>>) fixture.getOrDefault("projectTags", List.of());
143	        for (Map<String, Object> projectTag : projectTags) {
144	            long projectId = ((Number) projectTag.get("projectId")).longValue();
145	            long tagId = ((Number) projectTag.get("tagId")).longValue();
146	            jdbc.update("INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
147	                    projectId, tagId);
148	        }
149	
150	        List<Map<String, Object>> notes =
151	                (List<Map<String, Object>>) fixture.getOrDefault("notes", List.of());
152	        long maxNoteId = 0;
153	        for (Map<String, Object> note : notes) {
154	            long id = ((Number) note.get("id")).longValue();
155	            long targetId = ((Number) note.get("targetId")).longValue();
156	            jdbc.update(
157	                    "INSERT INTO notes (id, target_type, target_id, text, at) VALUES (?, ?, ?, ?, ?)",
158	                    id, note.get("targetType"), targetId, note.get("text"),
159	                    OffsetDateTime.parse((String) note.get("at")));
160	            maxNoteId = Math.max(maxNoteId, id);
161	        }
162	        if (maxNoteId > 0) {
163	            jdbc.execute("ALTER TABLE notes ALTER COLUMN id RESTART WITH " + (maxNoteId + 1));
164	        }
165	
166	        List<Map<String, Object>> invoices =
167	                (List<Map<String, Object>>) fixture.getOrDefault("invoices", List.of());
168	        long maxInvoiceId = 0;
169	        long maxLineItemId = 0;
170	        for (Map<String, Object> invoice : invoices) {
171	            long id = ((Number) invoice.get("id")).longValue();
172	            long projectId = ((Number) invoice.get("projectId")).longValue();
173	            // An invoice is itemised: its amount is derived as the sum of each line's qty * price.
174	            // A fixture may still pass an explicit amount for a line-item-less invoice.
175	            List<Map<String, Object>> lineItems =
176	                    (List<Map<String, Object>>) invoice.getOrDefault("lineItems", List.of());
177	            double amount = lineItems.isEmpty() && invoice.get("amount") != null
178	                    ? ((Number) invoice.get("amount")).doubleValue()
179	                    : 0;
180	            for (Map<String, Object> lineItem : lineItems) {
181	                amount += ((Number) lineItem.get("qty")).doubleValue()
182	                        * ((Number) lineItem.get("unitPrice")).doubleValue();
183	            }
184	            String status = (String) invoice.getOrDefault("status", "UNPAID");
185	            Object issuedDate = invoice.getOrDefault("issuedDate", LocalDate.now().toString());
186	            Object dueDate = invoice.getOrDefault("dueDate", LocalDate.now().toString());
187	            jdbc.update(
188	                    "INSERT INTO invoices (id, project_id, amount, status, issued_date, due_date) VALUES (?, ?, ?, ?, ?, ?)",
189	                    id, projectId, amount, status, issuedDate, dueDate);
190	            maxInvoiceId = Math.max(maxInvoiceId, id);
191	            for (Map<String, Object> lineItem : lineItems) {
192	                long lineItemId = ((Number) lineItem.get("id")).longValue();
193	                Object unit = lineItem.getOrDefault("unit", "unit");
194	                jdbc.update(
195	                        "INSERT INTO line_items (id, invoice_id, description, qty, unit, unit_price) VALUES (?, ?, ?, ?, ?, ?)",
196	                        lineItemId, id, lineItem.get("description"),
197	                        ((Number) lineItem.get("qty")).intValue(), unit, lineItem.get("unitPrice"));
198	                maxLineItemId = Math.max(maxLineItemId, lineItemId);
199	            }
200	        }
201	        if (maxInvoiceId > 0) {
202	            jdbc.execute("ALTER TABLE invoices ALTER COLUMN id RESTART WITH " + (maxInvoiceId + 1));
203	        }
204	        if (maxLineItemId > 0) {
205	            jdbc.execute("ALTER TABLE line_items ALTER COLUMN id RESTART WITH " + (maxLineItemId + 1));
206	        }
207	
